import React, { useState, useEffect } from 'react';
import { useLocation, Link } from 'react-router-dom';

const Header = ({ className }) => {
  const location = useLocation();
  const isMainPage = location.pathname === '/';

  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const updatedClassName = isMainPage ? className : 'header-scrolled';

  const scrollToSection = (id) => {
    const element = document.getElementById(id);
    if (element) {
      window.scrollTo({
        top: element.offsetTop,
        behavior: 'smooth',
      });
    }
  };

  const [imageSrc, setImageSrc] = useState('./images/doad_logo_fulltext_white.png');

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 640) {
        setImageSrc('./images/logo-white.png');
      } else {
        setImageSrc('./images/doad_logo_fulltext_white.png');
      }
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <header
      className={`fixed top-0 left-0 w-full text-white p-4 z-50 transition-all duration-500 ${updatedClassName}`}
      aria-label="Main Navigation"
    >
      <nav className="font-Montserrat container mx-auto flex justify-between items-center">
        {/* Brand Logo */}
        <div className="text-2xl font-bold">
          <img src={imageSrc} className="max-h-10 ml-7" alt="Doad Logo" />
        </div>

        {/* Desktop Menu */}
        <ul className="hidden md:flex space-x-4">
          {isMainPage ? (
            <>
              <li>
                <a
                  href="#work"
                  className="hover:underline"
                  onClick={(e) => {
                    e.preventDefault();
                    scrollToSection('work');
                  }}
                >
                  WORK
                </a>
              </li>
              <li>
                <a
                  href="#product"
                  className="hover:underline"
                  onClick={(e) => {
                    e.preventDefault();
                    scrollToSection('product');
                  }}
                >
                  SERVICES
                </a>
              </li>
              <li>
                <a
                  href="#about"
                  className="hover:underline"
                  onClick={(e) => {
                    e.preventDefault();
                    scrollToSection('about');
                  }}
                >
                  ABOUT
                </a>
              </li>
              <li>
                <a
                  href="#contact"
                  className="hover:underline"
                  onClick={(e) => {
                    e.preventDefault();
                    scrollToSection('contact');
                  }}
                >
                  CONTACT
                </a>
              </li>
            </>
          ) : (
            <>
              <li>
                <a href="/#work" className="hover:underline">
                  WORK
                </a>
              </li>
              <li>
                <a href="/#product" className="hover:underline">
                  SERVICES
                </a>
              </li>
              <li>
                <a href="/#about" className="hover:underline">
                  ABOUT
                </a>
              </li>
              <li>
                <a href="/#contact" className="hover:underline">
                  CONTACT
                </a>
              </li>
            </>
          )}
        </ul>

        {/* Hamburger Menu Icon */}
        <div className="md:hidden">
          <button
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="focus:outline-none"
            aria-label="Toggle menu"
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              className="w-8 h-8 text-white"
            >
              {isMenuOpen ? (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
              ) : (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
              )}
            </svg>
          </button>
        </div>
      </nav>

      {/* Mobile Menu Overlay */}
      {isMenuOpen && (
        <div className="fixed top-0 left-0 w-full h-screen bg-primary-light text-white z-40 flex flex-col items-center justify-center space-y-8 md:hidden">
          <ul className="text-center text-2xl">
            {isMainPage ? (
              <>
                <li>
                  <a
                    href="#work"
                    className="hover:underline"
                    onClick={(e) => {
                      e.preventDefault();
                      scrollToSection('work');
                      setIsMenuOpen(false);
                    }}
                  >
                    WORK
                  </a>
                </li>
                <li>
                  <a
                    href="#product"
                    className="hover:underline"
                    onClick={(e) => {
                      e.preventDefault();
                      scrollToSection('product');
                      setIsMenuOpen(false);
                    }}
                  >
                    SERVICES
                  </a>
                </li>
                <li>
                  <a
                    href="#about"
                    className="hover:underline"
                    onClick={(e) => {
                      e.preventDefault();
                      scrollToSection('about');
                      setIsMenuOpen(false);
                    }}
                  >
                    ABOUT US
                  </a>
                </li>
                <li>
                  <a
                    href="#contact"
                    className="hover:underline"
                    onClick={(e) => {
                      e.preventDefault();
                      scrollToSection('contact');
                      setIsMenuOpen(false);
                    }}
                  >
                    CONTACT US
                  </a>
                </li>
              </>
            ) : (
              <>
                <li>
                  <a href="/#work" className="hover:underline" onClick={() => setIsMenuOpen(false)}>
                    WORK
                  </a>
                </li>
                <li>
                  <a href="/#product" className="hover:underline" onClick={() => setIsMenuOpen(false)}>
                    SERVICES
                  </a>
                </li>
                <li>
                  <a href="/#about" className="hover:underline" onClick={() => setIsMenuOpen(false)}>
                    ABOUT US
                  </a>
                </li>
                <li>
                  <a href="/#contact" className="hover:underline" onClick={() => setIsMenuOpen(false)}>
                    CONTACT US
                  </a>
                </li>
              </>
            )}
          </ul>
        </div>
      )}
    </header>
  );
};

export default Header;
